/**
 * @file jszip.min.js
 * @description 轻量自包含纯原生 JS ZIP 打包器，兼容标准 JSZip API
 * 支持浏览器脱机环境与 Node.js 单元测试环境
 */

// CRC-32 校验表与计算
const makeCRCTable = () => {
  let c;
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    c = n;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[n] = c >>> 0;
  }
  return table;
};

const crcTable = makeCRCTable();

function crc32(bytes) {
  let crc = 0 ^ (-1);
  for (let i = 0; i < bytes.length; i++) {
    crc = (crc >>> 8) ^ crcTable[(crc ^ bytes[i]) & 0xFF];
  }
  return (crc ^ (-1)) >>> 0;
}

const textEncoder = typeof TextEncoder !== 'undefined' ? new TextEncoder() : {
  encode: (str) => {
    const utf8 = unescape(encodeURIComponent(str));
    const arr = new Uint8Array(utf8.length);
    for (let i = 0; i < utf8.length; i++) arr[i] = utf8.charCodeAt(i);
    return arr;
  }
};

class JSZip {
  constructor() {
    this.files = {};
  }

  /**
   * 添加文件到 ZIP
   * @param {string} name 文件名
   * @param {string|Uint8Array|ArrayBuffer|Blob} data 数据
   * @returns {JSZip}
   */
  file(name, data) {
    if (data === null || data === undefined) {
      delete this.files[name];
    } else {
      this.files[name] = data;
    }
    return this;
  }

  /**
   * 将数据统一转换为 Uint8Array
   * @private
   */
  async _normalizeData(data) {
    if (typeof data === 'string') {
      return textEncoder.encode(data);
    }
    if (data instanceof Uint8Array) {
      return data;
    }
    if (data instanceof ArrayBuffer) {
      return new Uint8Array(data);
    }
    if (typeof Blob !== 'undefined' && data instanceof Blob) {
      if (typeof data.arrayBuffer === 'function') {
        const buf = await data.arrayBuffer();
        return new Uint8Array(buf);
      }
      if (data.parts && Array.isArray(data.parts)) {
        let total = 0;
        for (const p of data.parts) total += p.length || p.byteLength || 0;
        const res = new Uint8Array(total);
        let off = 0;
        for (const p of data.parts) {
          const chunk = p instanceof Uint8Array ? p : new Uint8Array(p.buffer || p);
          res.set(chunk, off);
          off += chunk.length;
        }
        return res;
      }
      if (typeof FileReader !== 'undefined') {
        return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(new Uint8Array(reader.result));
          reader.onerror = reject;
          reader.readAsArrayBuffer(data);
        });
      }
    }
    // Node.js Buffer 兼容
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer(data)) {
      return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    }
    return textEncoder.encode(String(data));
  }

  /**
   * 异步生成 ZIP 文件
   * @param {Object} options { type: 'blob' | 'uint8array' | 'nodebuffer' | 'arraybuffer' }
   * @returns {Promise<Blob|Uint8Array|Buffer|ArrayBuffer>}
   */
  async generateAsync(options = {}) {
    const type = options.type || 'blob';
    const entries = [];
    let localOffset = 0;

    // 格式化当前时间为 DOS 日期和时间
    const now = new Date();
    const dosTime = ((now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1)) & 0xFFFF;
    const dosDate = (((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate()) & 0xFFFF;

    const fileNames = Object.keys(this.files);
    for (const name of fileNames) {
      const rawData = this.files[name];
      const bytes = await this._normalizeData(rawData);
      const nameBytes = textEncoder.encode(name);
      const fileCRC = crc32(bytes);
      const size = bytes.length;

      // Local file header (30 字节 + nameBytes.length)
      const localHeader = new Uint8Array(30 + nameBytes.length);
      const lview = new DataView(localHeader.buffer);

      lview.setUint32(0, 0x04034B50, true); // Local file header signature
      lview.setUint16(4, 0x0014, true);     // Version needed to extract (2.0)
      lview.setUint16(6, 0x0800, true);     // General purpose bit flag (UTF-8)
      lview.setUint16(8, 0x0000, true);     // Compression method (0 = Store)
      lview.setUint16(10, dosTime, true);   // Last mod file time
      lview.setUint16(12, dosDate, true);   // Last mod file date
      lview.setUint32(14, fileCRC, true);   // CRC-32
      lview.setUint32(18, size, true);      // Compressed size
      lview.setUint32(22, size, true);      // Uncompressed size
      lview.setUint16(26, nameBytes.length, true); // File name length
      lview.setUint16(28, 0, true);         // Extra field length
      localHeader.set(nameBytes, 30);

      entries.push({
        name,
        nameBytes,
        bytes,
        crc: fileCRC,
        size,
        localOffset,
        localHeader
      });

      localOffset += localHeader.length + bytes.length;
    }

    // 计算中央目录 (Central Directory)
    let centralDirSize = 0;
    const centralHeaders = [];

    for (const entry of entries) {
      // Central directory header (46 字节 + entry.nameBytes.length)
      const cHeader = new Uint8Array(46 + entry.nameBytes.length);
      const cview = new DataView(cHeader.buffer);

      cview.setUint32(0, 0x02014B50, true); // Central directory header signature
      cview.setUint16(4, 0x0014, true);     // Version made by (2.0)
      cview.setUint16(6, 0x0014, true);     // Version needed to extract (2.0)
      cview.setUint16(8, 0x0800, true);     // General purpose bit flag (UTF-8)
      cview.setUint16(10, 0x0000, true);    // Compression method (Store)
      cview.setUint16(12, dosTime, true);   // Last mod file time
      cview.setUint16(14, dosDate, true);   // Last mod file date
      cview.setUint32(16, entry.crc, true); // CRC-32
      cview.setUint32(20, entry.size, true);// Compressed size
      cview.setUint32(24, entry.size, true);// Uncompressed size
      cview.setUint16(28, entry.nameBytes.length, true); // File name length
      cview.setUint16(30, 0, true);         // Extra field length
      cview.setUint16(32, 0, true);         // Comment length
      cview.setUint16(34, 0, true);         // Disk number start
      cview.setUint16(36, 0, true);         // Internal file attributes
      cview.setUint32(38, 0, true);         // External file attributes
      cview.setUint32(42, entry.localOffset, true); // Relative offset of local header
      cHeader.set(entry.nameBytes, 46);

      centralHeaders.push(cHeader);
      centralDirSize += cHeader.length;
    }

    const centralDirOffset = localOffset;

    // End of central directory record (EOCD, 22 字节)
    const eocd = new Uint8Array(22);
    const eview = new DataView(eocd.buffer);
    eview.setUint32(0, 0x06054B50, true);     // EOCD signature
    eview.setUint16(4, 0, true);              // Number of this disk
    eview.setUint16(6, 0, true);              // Disk where central directory starts
    eview.setUint16(8, entries.length, true); // Number of central directory records on this disk
    eview.setUint16(10, entries.length, true);// Total number of central directory records
    eview.setUint32(12, centralDirSize, true);// Size of central directory
    eview.setUint32(16, centralDirOffset, true); // Offset of start of central directory
    eview.setUint16(20, 0, true);             // Comment length

    // 计算总输出字节大小
    const totalLength = centralDirOffset + centralDirSize + 22;
    const zipBytes = new Uint8Array(totalLength);
    let offset = 0;

    // 写入每个文件的本地头和文件体
    for (const entry of entries) {
      zipBytes.set(entry.localHeader, offset);
      offset += entry.localHeader.length;
      zipBytes.set(entry.bytes, offset);
      offset += entry.bytes.length;
    }

    // 写入中央目录头
    for (const cHeader of centralHeaders) {
      zipBytes.set(cHeader, offset);
      offset += cHeader.length;
    }

    // 写入 EOCD
    zipBytes.set(eocd, offset);

    // 按需求类型返回
    if (type === 'blob' && typeof Blob !== 'undefined') {
      return new Blob([zipBytes], { type: 'application/zip' });
    }
    if (type === 'uint8array') {
      return zipBytes;
    }
    if (type === 'arraybuffer') {
      return zipBytes.buffer;
    }
    if (type === 'nodebuffer' && typeof Buffer !== 'undefined') {
      return Buffer.from(zipBytes.buffer);
    }
    if (typeof Blob !== 'undefined') {
      return new Blob([zipBytes], { type: 'application/zip' });
    }
    return zipBytes;
  }
}

// 兼容全局挂载与模块导出
if (typeof window !== 'undefined') {
  window.JSZip = JSZip;
}
if (typeof globalThis !== 'undefined') {
  globalThis.JSZip = JSZip;
}

export { JSZip };
export default JSZip;
